python - <<'PY'
p = "packs/sketches/soundclash.yaml"
s = open(p, encoding="utf-8").read()

old_head = '''# Built for DJs who stream. A Set is a series of Rounds, and a Round is one
# transition: the app calls a mechanic, you do it on the decks, you press
# Next, and the next mechanic is already on screen. Nothing is declared,
# nothing is journalled, nothing is targeted. One press per Round is the
# whole interface, which is what makes it usable from a stream deck with a
# camera pointed at you.
#
# Four styles, one table each, chosen as the mode at the top of the Set:
# First Sets for somebody learning, Club Standard for the working
# vocabulary, Turntablism for scratch and juggle work, Open Format for
# genre and era whiplash. The fifth mode is the clash itself: the same
# Open Format table, two or more selectors trading Rounds.
#
# Written to show the one shape none of the other sketches use: a pack with
# no subjects and no roll step, where the call is an onEnterUnit trigger and
# the only press in a Round is the one that ends it.
'''
new_head = '''# Built for DJs who stream. A Set is a series of Rounds, and a Round is one
# transition: the app calls a mechanic, you do it on the decks, and you call
# the Round. Nothing is declared, nothing is journalled, nothing is targeted,
# so a whole Round is two presses -- call it, then Next -- and with Auto-roll
# and "carry on by itself" switched on, neither one waits for anything. That
# is the point of the pack: it has to be playable with a camera on you and a
# hand on a record.
#
# Four styles, one table each, chosen as the mode at the top of the Set:
# First Sets for somebody learning, Club Standard for the working
# vocabulary, Turntablism for scratch and juggle work, Open Format for
# genre and era whiplash. The fifth mode is the clash itself: the same
# Open Format table, two or more selectors trading Rounds.
#
# Written to show a pack with no subjects at all, and modes that differ by
# nothing except which phase they leave switched on.
'''
assert old_head in s
s = s.replace(old_head, new_head)

old_fix = s[s.index("fixtures:"):]
new_fix = '''fixtures:
  # The shape the whole pack is built around: a Round is a call and a Next,
  # and nothing is left over in between.
  - name: A Round is a call and a Next
    mode: clubStandard
    play:
      - { enter: 1 }
      - { step: callClub, answers: { d20: 1 } }
      - { step: mix }
      - { enter: 2 }
      - { step: callClub, answers: { d20: 8 } }
    expect:
      - { path: outcomes.length, equals: 2 }
      - { path: outcomes.0.entryId, equals: cs-01 }
      - { path: outcomes.1.entryId, equals: cs-08 }
      - { path: counters.rounds, equals: 1 }
      - { path: subjects.length, equals: 0 }
      - { path: status, equals: active }
      - { requests: answered }

  # Each mode calls from its own table and no other. Turntablism rolling a
  # 4 has to land on the flare, not on whatever a 4 means in Club Standard.
  - name: A mode calls from its own table and switches off the rest
    mode: turntablism
    play:
      - { enter: 1 }
      - { step: callTurntablism, answers: { d20: 4 } }
    expect:
      - { path: outcomes.length, equals: 1 }
      - { path: outcomes.0.table, equals: turntablism }
      - { path: outcomes.0.entryId, equals: tt-04 }
      - { requests: answered }

  # The clash is Open Format with people taking turns, so it calls the same
  # table the solo mode does.
  - name: The clash calls Open Format
    mode: clash
    play:
      - { enter: 1 }
      - { step: callOpen, answers: { d20: 13 } }
    expect:
      - { path: outcomes.0.table, equals: openFormat }
      - { path: outcomes.0.entryId, equals: of-13 }
      - { requests: answered }

  # A Pass spends one and leaves the Round without a call to honor.
  - name: A Pass costs one and the Round carries on
    mode: firstSets
    play:
      - { enter: 1 }
      - { step: callFirstSets, answers: { d20: 4 } }
      - { move: pass }
      - { step: mix }
    expect:
      - { path: resources.passes, equals: 2 }
      - { path: counters.rounds, equals: 1 }
      - { requests: answered }
'''
s = s.replace(old_fix, new_fix)
open(p, "w", encoding="utf-8", newline="\n").write(s)
print("ok")
