2	import { listSetups } from "../storage/db.ts";
3	import type { ControlProfile, ProfileOp } from "./profile.ts";
4	
5	/**
6	 * The setups that ship with the app.
7	 *
8	 * Read the way the shipped profiles are read, and for the same reason:
9	 * handing somebody a file to find and import before anything works is a
10	 * poor way to start a run.
11	 *
12	 * What is different is who they are for. A profile is written against a
13	 * pack, so the picker offers the pack's own. A setup is written against
14	 * a *tool*, and names no pack at all, so every setup for the tool this
15	 * run is talking to is on offer: the same seven fit any Elden Ring pack
16	 * somebody writes, which is the whole point of the document being its
17	 * own document.
18	 */
19	const files = import.meta.glob("../../../../packs/setups/*.yaml", { query: "?raw", import: "default" }) as Record<
20	  string,
21	  () => Promise<string>
22	>;
23	
24	let loaded: Setup[] | null = null;
25	
26	/** Every shipped setup, read once, in the order a list should show them. */
27	export async function shippedSetups(): Promise<Setup[]> {
28	  if (loaded) return loaded;
29	  const out: Setup[] = [];
30	  for (const read of Object.values(files)) {
31	    // One that does not parse is a bug in this repository rather than
32	    // something to put in front of anybody: `check:packs` validates every
33	    // one of these on the way in, so silence here is the right answer.
34	    const parsed = loadSetupText(await read(), "yaml");
35	    if (parsed.ok) out.push(parsed.setup);
36	  }
37	
38	  loaded = out.sort((a, b) => a.title.localeCompare(b.title));
39	  return loaded;
40	}
41	
42	/**
43	 * Every setup available here: the ones that ship, and the ones kept.
44	 *
45	 * Seven ship with the app. This is those plus whatever somebody added
46	 * from a file or from the marketplace, which is the difference between a
47	 * shelf and a fixed list. A kept one wins where the ids collide, on the
48	 * same rule the pack shelf uses: what you chose to keep beats what
49	 * happened to be in the bundle.
50	 *
51	 * A kept setup that no longer parses is left out rather than shown
52	 * broken. That can happen honestly: a file written against a later
53	 * version of the format than this build understands.
54	 */
55	export async function setupsHere(): Promise<Setup[]> {
56	  const byId = new Map((await shippedSetups()).map((s) => [s.id, s]));
57	  for (const kept of await listSetups()) {
58	    const parsed = loadSetupText(kept.source, kept.format);
59	    if (parsed.ok) byId.set(parsed.setup.id, parsed.setup);
60	  }
61	  return [...byId.values()].sort((a, b) => a.title.localeCompare(b.title));
62	}
63	
64	/**
65	 * The ones this run could actually use.
66	 *
67	 * A setup names its tool because operation names say nothing between
68	 * programs: two tools for two games could both have a `warp.position`,
69	 * and one meant for the other reaching this game would move somebody for
70	 * no reason. A run whose profile names no tool is talking to anything
71	 * that listens, and is offered nothing rather than everything.
72	 */
73	export function forTool(all: Setup[], tool: string | undefined): Setup[] {
74	  if (!tool) return [];
75	  return all.filter((s) => s.tool.toLowerCase() === tool.toLowerCase());
76	}
77	
