79	export interface SetupCredit {
80	  id: string;
81	  version: string;
82	  title: string;
83	}
84	
85	/**
86	 * What a run keeps of the setups it chose, and of what was done to them.
87	 *
88	 * Three things, and they answer three different questions. `ops` is what
89	 * will actually be sent, which is the only one the tool cares about.
90	 * `from` is where those operations came from, so a screen can still name
91	 * the setups. `edited` is whether they are still what those setups said.
92	 *
