attachment.snippet:
1	# Weapons, taken most of the way, without the mining.
2	#
3	# The amounts are a boost rather than a shopping trip: enough to stop
4	# the run being about materials, not so much that nothing is worth
5	# picking up. An ordinary weapon takes several stones a level and a
6	# somber one takes exactly one, which is why the two tiers differ.
7	
8	# yaml-language-server: $schema=../../packages/rules-schema/schema/setup-1.schema.json
9	
10	kind: setup
11	schemaVersion: 1
12	id: com.scrthq.runlog.setups.give-smithing-stones
13	version: "1.0.0"
14	title: Give Smithing Stones
15	author: Runlog
16	description: >-
17	  Enough of every smithing stone to take a couple of ordinary weapons to
18	  the top and a handful of somber ones with them. Ordinary stones go
19	  twenty to a tier because an ordinary weapon eats several a level;
20	  somber ones go eight, because a somber weapon eats exactly one.
21	
22	tool: TarnishedTool
23	
24	ops:
25	  - { op: item.named, args: { name: "Smithing Stone [1]", quantity: 20 }, once: true }
26	  - { op: item.named, args: { name: "Smithing Stone [2]", quantity: 20 }, once: true }
