30	  - { op: item.named, args: { name: "Smithing Stone [6]", quantity: 20 }, once: true }
31	  - { op: item.named, args: { name: "Smithing Stone [7]", quantity: 20 }, once: true }
32	  - { op: item.named, args: { name: "Smithing Stone [8]", quantity: 20 }, once: true }
